export const MONUMENTS = JSON.parse("[{\"id\":\"n6449209085\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"Р. Амундсен\",\"x\":-4611.5,\"z\":492.7,\"startDate\":\"2018-06-18\",\"subject\":\"Q926\",\"inscription\":\"Руал Амундсен — известный полярный исследователь\"},{\"id\":\"n6549720284\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. И. Бауману\",\"x\":-4600.1,\"z\":384.7,\"subject\":\"Q26693641\",\"inscription\":\"Здесь с 1895 по 1923 год жил и работал выдающийся деятель горной науки, основоположник отечественной маркшейдерской школы и разведочной геофизики профессор Владимир Иванович Бауман\"},{\"id\":\"n6549729285\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. А. Обручеву\",\"x\":-4606.4,\"z\":388.9,\"subject\":\"Q359568\",\"inscription\":\"Здесь с 1881 по 1886 г.г. учился геолог, географ и знаменитый путешественник, Герой Социалистического Труда академик Владимир Афанасьевич Обручев\"},{\"id\":\"n6549729286\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"П. Г. Соболевскому\",\"x\":-4609.8,\"z\":391.3,\"subject\":\"Q19117360\",\"inscription\":\"Здесь с 1824 по 1841 гг. работал крупнейший металлург, член-корреспондент Академии наук Пётр Григорьевич Соболевский\"},{\"id\":\"n6549729287\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Д. В. Наливкину\",\"x\":-4616.2,\"z\":395.7,\"subject\":\"Q1232728\",\"inscription\":\"Здесь с 1906 по 1982 гг. учился и работал выдающийся советский геолог, Герой Социалистического Труда, лауреат Ленинской премии и Государственной премии СССР академик Дмитрий Васильевич Наливкин\"},{\"id\":\"n3734060109\",\"kind\":\"memorial\",\"sub\":\"war_memorial\",\"name\":\"погибшим в ВОВ\",\"x\":-4633.3,\"z\":308.8}]");
